20	import * as zrUtil from 'zrender/src/core/util';
21	import VisualMapModel, { VisualMapOption, VisualMeta } from './VisualMapModel';
22	import * as numberUtil from '../../util/number';
23	import { VisualMappingOption } from '../../visual/VisualMapping';
24	import { inheritDefaultOption } from '../../util/component';
25	import { ItemStyleOption } from '../../util/types';
26	import tokens from '../../visual/tokens';
27	
28	// Constant
29	const DEFAULT_BAR_BOUND = [20, 140];
30	
31	type RangeWithAuto = {
32	    auto?: 0 | 1
33	};
34	
35	type VisualState = VisualMapModel['stateList'][number];
36	
37	export interface ContinousVisualMapOption extends VisualMapOption {
38	
39	    align?: 'auto' | 'left' | 'right' | 'top' | 'bottom'
40	
41	    /**
42	     * This prop effect default component type determine
43	     * @see echarts/component/visualMap/typeDefaulter.
44	     */
45	    calculable?: boolean
46	
47	    /**
48	     * selected range. In default case `range` is [min, max]
49	     * and can auto change along with modification of min max,
50	     * until user specified a range.
51	     */
52	    range?: number[]
53	    /**
54	     * Whether to enable hover highlight.
55	     */
56	    hoverLink?: boolean
57	
58	    /**
59	     * The extent of hovered data.
60	     */
61	    hoverLinkDataSize?: number
62	    /**
63	     * Whether trigger hoverLink when hover handle.
64	     * If not specified, follow the value of `realtime`.
65	     */
66	    hoverLinkOnHandle?: boolean,
67	
68	    handleIcon?: string,
69	    // Percent of the item width
70	    handleSize?: string | number,
71	    handleStyle?: ItemStyleOption
72	
73	    indicatorIcon?: string,
74	    // Percent of the item width
75	    indicatorSize?: string | number,
76	    indicatorStyle?: ItemStyleOption
77	
78	    emphasis?: {
79	        handleStyle?: ItemStyleOption
80	    }
81	}
82	
83	class ContinuousModel extends VisualMapModel<ContinousVisualMapOption> {
84	
85	    static type = 'visualMap.continuous' as const;
86	    type = ContinuousModel.type;
87	
88	    /**
89	     * @override
90	     */
91	    optionUpdated(newOption: ContinousVisualMapOption, isInit: boolean) {
92	        super.optionUpdated.apply(this, arguments as any);
93	
94	        this.resetExtent();
95	
96	        this.resetVisual(function (mappingOption?: VisualMappingOption) {
97	            mappingOption.mappingMethod = 'linear';
98	            mappingOption.dataExtent = this.getExtent();
99	        });
100	
101	        this._resetRange();
102	    }
103	
104	    /**
105	     * @protected
106	     * @override
107	     */
108	    resetItemSize() {
109	        super.resetItemSize.apply(this, arguments as any);
110	
111	        const itemSize = this.itemSize;
112	
113	        (itemSize[0] == null || isNaN(itemSize[0])) && (itemSize[0] = DEFAULT_BAR_BOUND[0]);
114	        (itemSize[1] == null || isNaN(itemSize[1])) && (itemSize[1] = DEFAULT_BAR_BOUND[1]);
115	    }
116	
117	    /**
118	     * @private
119	     */
120	    _resetRange() {
121	        const dataExtent = this.getExtent();
122	        const range = this.option.range;
123	
124	        if (!range || (range as RangeWithAuto).auto) {
125	            // `range` should always be array (so we don't use other
126	            // value like 'auto') for user-friend. (consider getOption).
127	            (dataExtent as RangeWithAuto).auto = 1;
128	            this.option.range = dataExtent;
129	        }
130	        else if (zrUtil.isArray(range)) {
131	            if (range[0] > range[1]) {
132	                range.reverse();
133	            }
134	            range[0] = Math.max(range[0], dataExtent[0]);
135	            range[1] = Math.min(range[1], dataExtent[1]);
136	        }
137	    }
138	
139	    /**
140	     * @protected
141	     * @override
142	     */
143	    completeVisualOption() {
144	        super.completeVisualOption.apply(this, arguments as any);
145	
146	        zrUtil.each(this.stateList, function (state: VisualState) {
147	            const symbolSize = this.option.controller[state].symbolSize;
148	            if (symbolSize && symbolSize[0] !== symbolSize[1]) {
149	                symbolSize[0] = symbolSize[1] / 3; // For good looking.
150	            }
151	        }, this);
152	    }
153	
154	    /**
155	     * @override
156	     */
157	    setSelected(selected: number[]) {
158	        this.option.range = selected.slice();
159	        this._resetRange();
160	    }
161	
162	    /**
163	     * @public
164	     */
165	    getSelected(): [number, number] {
166	        const dataExtent = this.getExtent();
167	
168	        const dataInterval = numberUtil.asc(
169	            (this.get('range') || []).slice()
170	        ) as [number, number];
171	
172	        // Clamp
173	        dataInterval[0] > dataExtent[1] && (dataInterval[0] = dataExtent[1]);
174	        dataInterval[1] > dataExtent[1] && (dataInterval[1] = dataExtent[1]);
175	        dataInterval[0] < dataExtent[0] && (dataInterval[0] = dataExtent[0]);
176	        dataInterval[1] < dataExtent[0] && (dataInterval[1] = dataExtent[0]);
177	
178	        return dataInterval;
179	    }
180	
181	    /**
182	     * @override
183	     */
184	    getValueState(value: number): VisualState {
185	        const range = this.option.range;
186	        const dataExtent = this.getExtent();
187	
188	        // When range[0] === dataExtent[0], any value larger than dataExtent[0] maps to 'inRange'.
189	        // range[1] is processed likewise.
190	        return (
191	            (range[0] <= dataExtent[0] || range[0] <= value)
192	            && (range[1] >= dataExtent[1] || value <= range[1])
193	        ) ? 'inRange' : 'outOfRange';
194	    }
195	
196	    findTargetDataIndices(range: number[]) {
197	        type DataIndices = {
198	            seriesId: string
199	            dataIndex: number[]
200	        };
201	        const result: DataIndices[] = [];
202	
203	        this.eachTargetSeries(function (seriesModel) {
204	            const dataIndices: number[] = [];
205	            const data = seriesModel.getData();
206	
207	            data.each(this.getDataDimensionIndex(data), function (value, dataIndex) {
208	                range[0] <= value && value <= range[1] && dataIndices.push(dataIndex);
209	            }, this);
210	
211	            result.push({
212	                seriesId: seriesModel.id,
213	                dataIndex: dataIndices
214	            });
215	        }, this);
216	
217	        return result;
218	    }
219	
220	    /**
221	     * @implement
222	     */
223	    getVisualMeta(
224	        getColorVisual: (value: number, valueState: VisualState) => string
225	    ) {
226	        type ColorStop = VisualMeta['stops'][number];
227	        const oVals = getColorStopValues(this, 'outOfRange', this.getExtent());
228	        const iVals = getColorStopValues(this, 'inRange', this.option.range.slice());
229	        const stops: ColorStop[] = [];
230	
231	        function setStop(value: number, valueState: VisualState) {
232	            stops.push({
233	                value: value,
234	                color: getColorVisual(value, valueState)
235	            });
236	        }
237	
238	        // Format to: outOfRange -- inRange -- outOfRange.
239	        let iIdx = 0;
240	        let oIdx = 0;
241	        const iLen = iVals.length;
242	        const oLen = oVals.length;
243	
244	        for (; oIdx < oLen && (!iVals.length || oVals[oIdx] <= iVals[0]); oIdx++) {
245	            // If oVal[oIdx] === iVals[iIdx], oVal[oIdx] should be ignored.
246	            if (oVals[oIdx] < iVals[iIdx]) {
247	                setStop(oVals[oIdx], 'outOfRange');
248	            }
249	        }
250	        for (let first = 1; iIdx < iLen; iIdx++, first = 0) {
251	            // If range is full, value beyond min, max will be clamped.
252	            // make a singularity
253	            first && stops.length && setStop(iVals[iIdx], 'outOfRange');
254	            setStop(iVals[iIdx], 'inRange');
255	        }
256	        for (let first = 1; oIdx < oLen; oIdx++) {
257	            if (!iVals.length || iVals[iVals.length - 1] < oVals[oIdx]) {
258	                // make a singularity
259	                if (first) {
260	                    stops.length && setStop(stops[stops.length - 1].value, 'outOfRange');
261	                    first = 0;
262	                }
263	                setStop(oVals[oIdx], 'outOfRange');
264	            }
265	        }
266	
267	        const stopsLen = stops.length;
268	
269	        return {
270	            stops: stops,
271	            outerColors: [
272	                stopsLen ? stops[0].color : 'transparent',
273	                stopsLen ? stops[stopsLen - 1].color : 'transparent'
274	            ] as VisualMeta['outerColors']
275	        };
276	    }
277	
278	    static defaultOption = inheritDefaultOption(VisualMapModel.defaultOption, {
279	        align: 'auto',           // 'auto', 'left', 'right', 'top', 'bottom'
280	        calculable: false,
281	        hoverLink: true,
282	        realtime: true,
283	
284	        handleIcon: 'path://M-11.39,9.77h0a3.5,3.5,0,0,1-3.5,3.5h-22a3.5,3.5,0,0,1-3.5-3.5h0a3.5,3.5,0,0,1,3.5-3.5h22A3.5,3.5,0,0,1-11.39,9.77Z',
285	        handleSize: '120%',
286	
287	        handleStyle: {
288	            borderColor: tokens.color.neutral00,
289	            borderWidth: 1
290	        },
291	
292	        indicatorIcon: 'circle',
293	        indicatorSize: '50%',
294	        indicatorStyle: {
295	            borderColor: tokens.color.neutral00,
296	            borderWidth: 2,
297	            shadowBlur: 2,
298	            shadowOffsetX: 1,
299	            shadowOffsetY: 1,
300	            shadowColor: tokens.color.shadow
301	        }
302	        // emphasis: {
303	        //     handleStyle: {
304	        //         shadowBlur: 3,
305	        //         shadowOffsetX: 1,
306	        //         shadowOffsetY: 1,
307	        //         shadowColor: tokens.color.shadow
308	        //     }
309	        // }
310	    }) as ContinousVisualMapOption;
311	}
312	
313	
314	function getColorStopValues(
315	    visualMapModel: ContinuousModel,
316	    valueState: VisualState,
317	    dataExtent: number[]
318	) {
319	    if (dataExtent[0] === dataExtent[1]) {
320	        return dataExtent.slice();
321	    }
322	
323	    // When using colorHue mapping, it is not linear color any more.
324	    // Moreover, canvas gradient seems not to be accurate linear.
325	    // FIXME
326	    // Should be arbitrary value 100? or based on pixel size?
327	    const count = 200;
328	    const step = (dataExtent[1] - dataExtent[0]) / count;
329	
330	    let value = dataExtent[0];
331	    const stopValues = [];
332	    for (let i = 0; i <= count && value < dataExtent[1]; i++) {
333	        stopValues.push(value);
334	        value += step;
335	    }
336	    stopValues.push(dataExtent[1]);
337	
338	    return stopValues;
339	}
340	
341	export default ContinuousModel;
