51	
52	type VisualOptionBase = {[key in BuiltinVisualProperty]?: any};
53	
54	type LabelFormatter = (min: OptionDataValue, max?: OptionDataValue) => string;
55	
56	type VisualState = VisualMapModel['stateList'][number];
57	export interface VisualMapOption<T extends VisualOptionBase = VisualOptionBase> extends
58	    ComponentOption,
59	    BoxLayoutOptionMixin,
60	    BorderOptionMixin {
61	
62	    mainType?: 'visualMap'
63	
64	    show?: boolean
65	
66	    align?: string
67	
68	    realtime?: boolean
69	    /**
70	     * 'all' or null/undefined: all series.
71	     * A number or an array of number: the specified series.
72	     */
73	    seriesIndex?: 'all' | number[] | number
74	    seriesId?: OptionId | OptionId[]
75	
76	    /**
77	     * set min: 0, max: 200, only for campatible with ec2.
78	     * In fact min max should not have default value.
79	     * min value, must specified if pieces is not specified.
80	     */
81	    min?: number
82	
83	    /**
84	     * max value, must specified if pieces is not specified.
85	     */
86	    max?: number
87	    /**
88	     * Dimension to be encoded
89	     */
90	    dimension?: number
91	
92	    /**
93	     * Visual configuration for the data in selection
94	     */
95	    inRange?: T
96	    /**
97	     * Visual configuration for the out of selection
98	     */
99	    outOfRange?: T
100	
101	    controller?: {
102	        inRange?: T
103	        outOfRange?: T
104	    }
105	    target?: {
106	        inRange?: T
107	        outOfRange?: T
108	    }
109	
110	    /**
111	     * Width of the display item
112	     */
113	    itemWidth?: number
114	    /**
115	     * Height of the display item
116	     */
117	    itemHeight?: number
118	
119	    inverse?: boolean
120	
121	    orient?: 'horizontal' | 'vertical'
122	
123	    backgroundColor?: ZRColor
124	    contentColor?: ZRColor
125	
126	    inactiveColor?: ZRColor
127	
128	    /**
129	     * Padding of the component. Can be an array similar to CSS
130	     */
131	    padding?: number[] | number
132	    /**
133	     * Gap between text and item
134	     */
135	    textGap?: number
136	
137	    precision?: number
138	
139	    /**
140	     * @deprecated
141	     * Option from version 2
142	     */
143	    color?: ColorString[]
144	
