146	
147	    /**
148	     * Text on the both end. Such as ['High', 'Low']
149	     */
150	    text?: string[]
151	
152	    textStyle?: LabelOption
153	
154	
155	    categories?: unknown
156	}
157	
158	export interface VisualMeta {
159	    stops: { value: number, color: ColorString}[]
160	    outerColors: ColorString[]
161	
162	    dimension?: DimensionIndex
163	}
164	
165	class VisualMapModel<Opts extends VisualMapOption = VisualMapOption> extends ComponentModel<Opts> {
166	
167	    static type = 'visualMap';
168	    type = VisualMapModel.type;
169	
170	    static readonly dependencies = ['series'];
171	
172	    readonly stateList = ['inRange', 'outOfRange'] as const;
173	
174	    readonly replacableOptionKeys = [
175	        'inRange', 'outOfRange', 'target', 'controller', 'color'
176	    ] as const;
177	
178	    readonly layoutMode = {
179	        type: 'box', ignoreSize: true
180	    } as const;
181	
182	    /**
183	     * [lowerBound, upperBound]
184	     */
185	    dataBound = [-Infinity, Infinity];
186	
187	    protected _dataExtent: [number, number];
188	
189	    targetVisuals = {} as ReturnType<typeof visualSolution.createVisualMappings>;
190	
191	    controllerVisuals = {} as ReturnType<typeof visualSolution.createVisualMappings>;
192	
193	    textStyleModel: Model<LabelOption>;
194	
195	    itemSize: number[];
196	
197	    init(option: Opts, parentModel: Model, ecModel: GlobalModel) {
198	        this.mergeDefaultAndTheme(option, ecModel);
199	    }
200	
201	    /**
202	     * @protected
203	     */
204	    optionUpdated(newOption: Opts, isInit?: boolean) {
205	        const thisOption = this.option;
206	
207	        !isInit && visualSolution.replaceVisualOption(
208	            thisOption, newOption, this.replacableOptionKeys
209	        );
210	
211	        this.textStyleModel = this.getModel('textStyle');
212	
213	        this.resetItemSize();
214	
215	        this.completeVisualOption();
216	    }
217	
218	    /**
219	     * @protected
220	     */
221	    resetVisual(
222	        supplementVisualOption: (this: this, mappingOption: VisualMappingOption, state: string) => void
223	    ) {
224	        const stateList = this.stateList;
225	        supplementVisualOption = zrUtil.bind(supplementVisualOption, this);
226	
227	        this.controllerVisuals = visualSolution.createVisualMappings(
228	            this.option.controller, stateList, supplementVisualOption
229	        );
230	        this.targetVisuals = visualSolution.createVisualMappings(
231	            this.option.target, stateList, supplementVisualOption
232	        );
233	    }
234	
235	    /**
236	     * @public
237	     */
238	    getItemSymbol(): string {
239	        return null;
240	    }
241	
242	    /**
243	     * @return An array of series indices.
244	     */
245	    protected getTargetSeriesIndices(): number[] {
246	        const optionSeriesId = this.option.seriesId;
247	        let optionSeriesIndex = this.option.seriesIndex;
248	        if (optionSeriesIndex == null && optionSeriesId == null) {
249	            optionSeriesIndex = 'all';
250	        }
251	
252	        const seriesModels = modelUtil.queryReferringComponents(
253	            this.ecModel,
254	            'series',
255	            {
256	                index: optionSeriesIndex,
257	                id: optionSeriesId,
258	            },
259	            {
260	                useDefault: false,
261	                enableAll: true,
262	                enableNone: false,
263	            }
264	        ).models;
265	
266	        return zrUtil.map(seriesModels, seriesModel => seriesModel.componentIndex);
267	    }
268	
269	    /**
270	     * @public
271	     */
272	    eachTargetSeries<Ctx>(
273	        callback: (this: Ctx, series: SeriesModel) => void,
274	        context?: Ctx
275	    ) {
276	        zrUtil.each(this.getTargetSeriesIndices(), function (seriesIndex) {
277	            const seriesModel = this.ecModel.getSeriesByIndex(seriesIndex);
278	            if (seriesModel) {
279	                callback.call(context, seriesModel);
280	            }
281	        }, this);
282	    }
283	
284	    /**
285	     * @pubilc
286	     */
287	    isTargetSeries(seriesModel: SeriesModel) {
288	        let is = false;
289	        this.eachTargetSeries(function (model) {
290	            model === seriesModel && (is = true);
291	        });
292	        return is;
293	    }
294	
295	    /**
296	     * @example
297	     * this.formatValueText(someVal); // format single numeric value to text.
298	     * this.formatValueText(someVal, true); // format single category value to text.
299	     * this.formatValueText([min, max]); // format numeric min-max to text.
300	     * this.formatValueText([this.dataBound[0], max]); // using data lower bound.
301	     * this.formatValueText([min, this.dataBound[1]]); // using data upper bound.
302	     *
303	     * @param value Real value, or this.dataBound[0 or 1].
304	     * @param isCategory Only available when value is number.
305	     * @param edgeSymbols Open-close symbol when value is interval.
306	     * @protected
307	     */
308	    formatValueText(
309	        value: number | string | number[],
310	        isCategory?: boolean,
311	        edgeSymbols?: string[]
312	    ): string {
313	        const option = this.option;
314	        const precision = option.precision;
315	        const dataBound = this.dataBound;
316	        const formatter = option.formatter;
317	        let isMinMax: boolean;
318	        edgeSymbols = edgeSymbols || ['<', '>'] as [string, string];
319	
320	        if (zrUtil.isArray(value)) {
321	            value = value.slice();
322	            isMinMax = true;
323	        }
324	
325	        const textValue = isCategory
326	            ? value as string   // Value is string when isCategory
327	            : (isMinMax
328	                ? [toFixed((value as number[])[0]), toFixed((value as number[])[1])]
329	                : toFixed(value as number)
330	            );
331	
332	        if (zrUtil.isString(formatter)) {
333	            return formatter
334	                .replace('{value}', isMinMax ? (textValue as string[])[0] : textValue as string)
335	                .replace('{value2}', isMinMax ? (textValue as string[])[1] : textValue as string);
336	        }
337	        else if (zrUtil.isFunction(formatter)) {
338	            return isMinMax
339	                ? formatter((value as number[])[0], (value as number[])[1])
340	                : formatter(value as number);
341	        }
342	
343	        if (isMinMax) {
344	            if ((value as number[])[0] === dataBound[0]) {
345	                return edgeSymbols[0] + ' ' + textValue[1];
346	            }
347	            else if ((value as number[])[1] === dataBound[1]) {
348	                return edgeSymbols[1] + ' ' + textValue[0];
349	            }
350	            else {
351	                return textValue[0] + ' - ' + textValue[1];
352	            }
353	        }
354	        else { // Format single value (includes category case).
355	            return textValue as string;
356	        }
357	
358	        function toFixed(val: number) {
359	            return val === dataBound[0]
360	                ? 'min'
361	                : val === dataBound[1]
362	                ? 'max'
363	                : (+val).toFixed(Math.min(precision, 20));
364	        }
365	    }
366	
367	    /**
368	     * @protected
369	     */
370	    resetExtent() {
371	        const thisOption = this.option;
372	
373	        // Can not calculate data extent by data here.
374	        // Because series and data may be modified in processing stage.
375	        // So we do not support the feature "auto min/max".
376	
377	        const extent = asc([thisOption.min, thisOption.max] as [number, number]);
378	
379	        this._dataExtent = extent;
