426	    completeVisualOption() {
427	
428	        const ecModel = this.ecModel;
429	        const thisOption = this.option;
430	        const base = {
431	            inRange: thisOption.inRange,
432	            outOfRange: thisOption.outOfRange
433	        };
434	
435	        const target = thisOption.target || (thisOption.target = {});
436	        const controller = thisOption.controller || (thisOption.controller = {});
437	
438	        zrUtil.merge(target, base); // Do not override
439	        zrUtil.merge(controller, base); // Do not override
440	
441	        const isCategory = this.isCategory();
442	
443	        completeSingle.call(this, target);
444	        completeSingle.call(this, controller);
445	        completeInactive.call(this, target, 'inRange', 'outOfRange');
446	        // completeInactive.call(this, target, 'outOfRange', 'inRange');
447	        completeController.call(this, controller);
448	
449	        function completeSingle(this: VisualMapModel, base: VisualMapOption['target']) {
450	            // Compatible with ec2 dataRange.color.
451	            // The mapping order of dataRange.color is: [high value, ..., low value]
452	            // whereas inRange.color and outOfRange.color is [low value, ..., high value]
453	            // Notice: ec2 has no inverse.
454	            if (isArray(thisOption.color)
455	                // If there has been inRange: {symbol: ...}, adding color is a mistake.
456	                // So adding color only when no inRange defined.
457	                && !base.inRange
458	            ) {
459	                base.inRange = {color: thisOption.color.slice().reverse()};
460	            }
461	
462	            // Compatible with previous logic, always give a default color, otherwise
463	            // simple config with no inRange and outOfRange will not work.
464	            // Originally we use visualMap.color as the default color, but setOption at
465	            // the second time the default color will be erased. So we change to use
466	            // constant DEFAULT_COLOR.
467	            // If user do not want the default color, set inRange: {color: null}.
468	            base.inRange = base.inRange || {color: ecModel.get('gradientColor')};
469	        }
470	
471	        function completeInactive(
472	            this: VisualMapModel,
473	            base: VisualMapOption['target'],
474	            stateExist: VisualState,
475	            stateAbsent: VisualState
476	        ) {
477	            const optExist = base[stateExist];
478	            let optAbsent = base[stateAbsent];
479	
480	            if (optExist && !optAbsent) {
481	                optAbsent = base[stateAbsent] = {};
482	                each(optExist, function (visualData, visualType: BuiltinVisualProperty) {
483	                    if (!VisualMapping.isValidType(visualType)) {
484	                        return;
485	                    }
486	
487	                    const defa = visualDefault.get(visualType, 'inactive', isCategory);
488	
489	                    if (defa != null) {
490	                        optAbsent[visualType] = defa;
491	
492	                        // Compatibable with ec2:
493	                        // Only inactive color to rgba(0,0,0,0) can not
494	                        // make label transparent, so use opacity also.
495	                        if (visualType === 'color'
496	                            && !optAbsent.hasOwnProperty('opacity')
497	                            && !optAbsent.hasOwnProperty('colorAlpha')
498	                        ) {
499	                            optAbsent.opacity = [0, 0];
500	                        }
501	                    }
502	                });
503	            }
504	        }
505	
506	        function completeController(this: VisualMapModel, controller?: VisualMapOption['controller']) {
507	            const symbolExists = (controller.inRange || {}).symbol
508	                || (controller.outOfRange || {}).symbol;
509	            const symbolSizeExists = (controller.inRange || {}).symbolSize
510	                || (controller.outOfRange || {}).symbolSize;
511	            const inactiveColor = this.get('inactiveColor');
512	            const itemSymbol = this.getItemSymbol();
513	            const defaultSymbol = itemSymbol || 'roundRect';
514	
515	            each(this.stateList, function (state: VisualState) {
516	
517	                const itemSize = this.itemSize;
518	                let visuals = controller[state];
519	
520	                // Set inactive color for controller if no other color
521	                // attr (like colorAlpha) specified.
522	                if (!visuals) {
523	                    visuals = controller[state] = {
524	                        color: isCategory ? inactiveColor : [inactiveColor]
525	                    };
526	                }
527	
528	                // Consistent symbol and symbolSize if not specified.
529	                if (visuals.symbol == null) {
530	                    visuals.symbol = symbolExists
531	                        && zrUtil.clone(symbolExists)
532	                        || (isCategory ? defaultSymbol : [defaultSymbol]);
533	                }
534	                if (visuals.symbolSize == null) {
535	                    visuals.symbolSize = symbolSizeExists
536	                        && zrUtil.clone(symbolSizeExists)
537	                        || (isCategory ? itemSize[0] : [itemSize[0], itemSize[0]]);
538	                }
539	
540	                // Filter none
541	                visuals.symbol = mapVisual(visuals.symbol, function (symbol) {
542	                    return symbol === 'none' ? defaultSymbol : symbol;
543	                });
544	
545	                // Normalize symbolSize
546	                const symbolSize = visuals.symbolSize;
547	
548	                if (symbolSize != null) {
549	                    let max = -Infinity;
550	                    // symbolSize can be object when categories defined.
551	                    eachVisual(symbolSize, function (value) {
552	                        value > max && (max = value);
553	                    });
554	                    visuals.symbolSize = mapVisual(symbolSize, function (value) {
555	                        return linearMap(value, [0, max], [0, itemSize[0]], true);
556	                    });
557	                }
558	
559	            }, this);
560	        }
561	    }
