28	export const visualMapEncodingHandlers: StageHandler[] = [
29	    {
30	        createOnAllSeries: true,
31	        reset: function (seriesModel, ecModel) {
32	            const resetDefines: StageHandlerProgressExecutor[] = [];
33	            ecModel.eachComponent('visualMap', function (visualMapModel: VisualMapModel) {
34	                const pipelineContext = seriesModel.pipelineContext;
35	                if (!visualMapModel.isTargetSeries(seriesModel)
36	                    || (pipelineContext && pipelineContext.large)
37	                ) {
38	                    return;
39	                }
40	
41	                resetDefines.push(visualSolution.incrementalApplyVisual(
42	                    visualMapModel.stateList,
43	                    visualMapModel.targetVisuals,
44	                    zrUtil.bind(visualMapModel.getValueState, visualMapModel),
45	                    visualMapModel.getDataDimensionIndex(seriesModel.getData())
46	                ));
47	            });
48	
49	            return resetDefines;
50	        }
51	    },
52	    // Only support color.
53	    {
54	        createOnAllSeries: true,
55	        reset: function (seriesModel, ecModel) {
56	            const data = seriesModel.getData();
57	            const visualMetaList: VisualMeta[] = [];
58	
59	            ecModel.eachComponent('visualMap', function (visualMapModel: VisualMapModel) {
60	                if (visualMapModel.isTargetSeries(seriesModel)) {
61	                    const visualMeta = visualMapModel.getVisualMeta(
62	                        zrUtil.bind(getColorVisual, null, seriesModel, visualMapModel)
63	                    ) || {
64	                        stops: [],
65	                        outerColors: []
66	                    } as VisualMeta;
67	
68	                    const dimIdx = visualMapModel.getDataDimensionIndex(data);
69	                    if (dimIdx >= 0) {
70	                        // visualMeta.dimension should be dimension index, but not concrete dimension.
71	                        visualMeta.dimension = dimIdx;
72	                        visualMetaList.push(visualMeta);
73	                    }
74	                }
75	            });
76	
77	            // console.log(JSON.stringify(visualMetaList.map(a => a.stops)));
78	            seriesModel.getData().setVisual('visualMeta', visualMetaList);
79	        }
80	    }
